import React, { useState } from 'react';

const faqData = [
  {
    category: "ORDERS & PAYMENT",
    questions: [
      {
        q: "How to place an order?",
        a: "To place an order, simply browse our collections, select your desired items and size, and click 'Add to Bag'. Once you're ready, proceed to checkout from your cart, enter your shipping and payment details, and confirm your order."
      },
      {
        q: "How do I use my BINDASS!! Money?",
        a: "BINDASS!! Money is our store credit system. During checkout, you can select 'BINDASS!! Money' as a payment method to apply your available balance toward your purchase."
      },
      {
        q: "Can I place an order on Cash On Delivery?",
        a: "Yes, we offer Cash On Delivery (COD) for most pin codes across India. You will see the option at checkout if it is available for your location."
      },
      {
        q: "Do I have to have an account to place an order at BINDASS!!?",
        a: "While you can checkout as a guest, we recommend creating an account to track your orders, manage your wishlist, and enjoy exclusive member benefits."
      },
      {
        q: "Can I ship the products to an address that is different from my billing address?",
        a: "Absolutely! During checkout, you can provide separate addresses for shipping and billing."
      },
      {
        q: "Can I order a product that is Out of Stock?",
        a: "Products that are out of stock cannot be ordered immediately. However, you can sign up for 'Notify Me' on the product page to be alerted once it's back in stock."
      },
      {
        q: "Can I leave items in my shopping bag for future purchase?",
        a: "Yes, items added to your bag will remain there for a limited time. For long-term saving, we recommend adding items to your Wishlist."
      },
      {
        q: "Can I buy multiple products in a single order?",
        a: "Yes, you can add as many items as you like to your shopping bag and checkout all of them at once."
      },
      {
        q: "Why is my order not showing?",
        a: "If your order isn't visible in 'My Orders', please ensure you are logged into the correct account. If the issue persists, contact our support team with your transaction details."
      },
      {
        q: "What do I do in cases of failed delivery?",
        a: "If a delivery attempt fails, our courier partner will usually attempt delivery again on the next business day. You can also contact us for assistance."
      },
      {
        q: "How do I use my BINDASS!! Points?",
        a: "Points earned through our loyalty program can be converted into discounts during the final step of checkout."
      },
      {
        q: "How do I know if my order was placed successfully?",
        a: "Once your order is confirmed, you will receive an email and a WhatsApp/SMS confirmation with your order ID and summary."
      }
    ]
  },
  {
    category: "SHIPPING & TRACKING",
    questions: [
      {
        q: "Can I modify the shipping address of my order before it has been shipped?",
        a: "Yes, you can modify your shipping address if the order hasn't been dispatched yet. Please contact support immediately or check your Order Details page."
      },
      {
        q: "How long will it take for my order to be delivered?",
        a: "Typically, orders are delivered within 3-7 business days depending on your location."
      },
      {
        q: "When will my products on pre-order be shipped?",
        a: "Pre-order items are shipped according to the date mentioned on the product page at the time of purchase."
      },
      {
        q: "Are there any additional shipping charges?",
        a: "Standard shipping is free on orders above a certain value. For orders below that, a nominal shipping fee may apply, which will be shown at checkout."
      },
      {
        q: "How do I track my order?",
        a: "You can track your order through the 'Track Order' link in your confirmation email or by visiting the 'My Orders' section in your account."
      },
      {
        q: "What if my order is undelivered?",
        a: "If your order is returned to us as undelivered, we will contact you for a re-delivery or process a refund as per our policy."
      },
      {
        q: "Does BINDASS!! have any physical stores?",
        a: "Currently, BINDASS!! is an exclusive online luxury destination, allowing us to bring premium fashion directly to you anywhere."
      },
      {
        q: "How can I track my Return Status?",
        a: "Return tracking is available in the 'My Returns' section of your account once a return request has been initiated."
      },
      {
        q: "Are there any cancellation charges?",
        a: "No, we do not charge for cancellations if they are made before the order is dispatched."
      },
      {
        q: "What is the estimated delivery time?",
        a: "Estimated delivery times are provided at checkout based on your pincode."
      },
      {
        q: "What if my order shows delivered but I've not received it?",
        a: "Please check with your neighbors or concierge first. If you still can't find it, contact us within 24 hours of the delivery notification."
      }
    ]
  },
  {
    category: "GIFT CARD FAQ",
    questions: [
      {
        q: "What denominations are gift cards available in?",
        a: "BINDASS!! Gift Cards are available in denominations ranging from ₹500 to ₹10,000."
      },
      {
        q: "How do I use my gift card balance?",
        a: "Enter your Gift Card code and PIN during the payment step of checkout to apply the balance to your total."
      },
      {
        q: "How are returns processed against gift card purchases?",
        a: "Refunds for orders paid via gift cards are credited back to the original gift card or issued as a new digital gift card/store credit."
      },
      {
        q: "How long are my gift cards valid for?",
        a: "BINDASS!! Gift Cards are typically valid for 12 months from the date of issuance."
      }
    ]
  },
  {
    category: "RETURNS, EXCHANGE & REFUND",
    questions: [
      {
        q: "What are the terms of the exchange policy?",
        a: "We offer an easy exchange policy within 15 days of delivery, provided the item is unused, unwashed, and has all original tags intact."
      },
      {
        q: "How do I create a exchange request?",
        a: "Go to 'My Orders', select the item you wish to exchange, and click on the 'Exchange' button to choose your new size or product."
      },
      {
        q: "I have created a exchange request. When will the product be picked up?",
        a: "The pick-up is usually scheduled within 24-48 business hours of your request being approved."
      },
      {
        q: "When will I get my exchanged product delivered?",
        a: "Once your original item passes quality check at our warehouse, your new item will be dispatched."
      },
      {
        q: "What are the terms of the Return Policy?",
        a: "Returns are accepted within 15 days of delivery. The product must be in its original condition with all packaging and tags."
      },
      {
        q: "How do I create a return request?",
        a: "Visit 'My Orders', select the items you wish to return, and follow the simple steps to create a return request."
      },
      {
        q: "I have created a return request. When will the product be picked up?",
        a: "Our courier partner will arrive for the pick-up within 2-3 business days of your request."
      },
      {
        q: "Where should I self-ship the returns?",
        a: "In rare cases where pick-up is unavailable, our team will provide you with the warehouse address for self-shipment."
      },
      {
        q: "My product has been picked up but I have not got my refund yet.",
        a: "Refunds are processed after the item reaches our warehouse and passes quality check. This usually takes 5-7 business days."
      },
      {
        q: "The product I want to return was bought on discount. Will I get refunded the full amount?",
        a: "You will be refunded the actual amount paid at the time of purchase, including any discounts applied."
      },
      {
        q: "In case I return the products, will the COD/Shipping/Gifting charges be credited back?",
        a: "Shipping and COD charges are non-refundable. Only the product value will be credited back."
      },
      {
        q: "Is there a convenience fee to get a refund?",
        a: "We do not charge any convenience fee for processing standard returns and refunds."
      }
    ]
  },
  {
    category: "SALE TERMS & CONDITIONS",
    questions: [
      {
        q: "Are sale items eligible for return?",
        a: "Items purchased during major sale events may have restricted return policies. Please check the specific product page for details."
      },
      {
        q: "Can I use additional coupons on sale items?",
        a: "Coupons may not be combinable with already discounted sale prices unless specified otherwise."
      }
    ]
  },
  {
    category: "EXCLUSIVE MEMBERSHIP",
    questions: [
      {
        q: "What is Club BINDASS!!?",
        a: "Club BINDASS!! is our premier loyalty program offering early access to drops, exclusive discounts, and premium concierge services."
      },
      {
        q: "How do I join the membership?",
        a: "Membership is automatically granted based on your annual spending, or can be purchased directly from the Membership page."
      }
    ]
  },
  {
    category: "MISCELLANEOUS",
    questions: [
      {
        q: "How do I contact customer support?",
        a: "You can reach us via the Contact Us page, email us at support@bindass.com, or use the live chat widget on our site."
      },
      {
        q: "Where can I find sizing information?",
        a: "A detailed Size Guide is available on every product page to help you find the perfect fit."
      }
    ]
  }
];

const FAQ = () => {
  const [activeCategory, setActiveCategory] = useState(faqData[0].category);
  const [openQuestion, setOpenQuestion] = useState(null);

  const toggleQuestion = (index) => {
    setOpenQuestion(openQuestion === index ? null : index);
  };

  const handleCategoryChange = (category) => {
    setActiveCategory(category);
    setOpenQuestion(null);
  };

  const currentQuestions = faqData.find(c => c.category === activeCategory).questions;

  return (
    <div className="min-h-screen bg-white font-['Manrope'] py-12 md:py-20">
      <div className="max-w-[1440px] mx-auto px-4 md:px-8 lg:px-12">
        {/* Header */}
        <div className="mb-12 md:mb-16">
          <h1 className="text-3xl md:text-4xl font-extrabold tracking-tighter uppercase mb-2">Help Center</h1>
          <p className="text-slate-500 text-sm md:text-base font-medium">Find answers to frequently asked questions about BINDASS!!</p>
        </div>

        <div className="flex flex-col lg:flex-row gap-12 lg:gap-20">
          {/* Sidebar - Categories */}
          <aside className="w-full lg:w-72 flex-shrink-0">
            <div className="lg:sticky lg:top-32">
              <h2 className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400 mb-6 hidden lg:block">Categories</h2>

              {/* Mobile Category Selector */}
              <div className="lg:hidden mb-8">
                 <select 
                    value={activeCategory}
                    onChange={(e) => handleCategoryChange(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-3 text-xs font-bold uppercase tracking-widest focus:outline-none focus:ring-2 focus:ring-emerald-500/20"
                 >
                    {faqData.map(cat => (
                      <option key={cat.category} value={cat.category}>{cat.category}</option>
                    ))}
                 </select>
              </div>

              {/* Desktop Category List */}
              <ul className="hidden lg:flex flex-col gap-2">
                {faqData.map((cat) => (
                  <li key={cat.category}>
                    <button
                      onClick={() => handleCategoryChange(cat.category)}
                      className={`w-full text-left px-4 py-3 text-[11px] font-bold uppercase tracking-widest transition-all duration-300 flex items-center justify-between group
                        ${activeCategory === cat.category 
                          ? 'bg-[#10221c] text-white shadow-lg translate-x-1' 
                          : 'text-slate-500 hover:bg-slate-50 hover:text-[#10221c]'
                        }`}
                    >
                      {cat.category}
                      <span className={`material-icons-outlined text-sm transition-transform duration-300 
                        ${activeCategory === cat.category ? 'translate-x-0' : '-translate-x-2 opacity-0 group-hover:opacity-100 group-hover:translate-x-0'}`}
                      >
                        chevron_right
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          </aside>

          {/* Main Content - Accordion */}
          <div className="flex-1 max-w-3xl">
            <div className="mb-8 flex items-center gap-4">
               <div className="h-px bg-slate-100 flex-1"></div>
               <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-emerald-600">{activeCategory}</h3>
               <div className="h-px bg-slate-100 flex-1"></div>
            </div>

            <div className="space-y-4">
              {currentQuestions.map((item, idx) => (
                <div 
                  key={idx} 
                  className={`border-b border-slate-100 transition-all duration-300 ${openQuestion === idx ? 'pb-6' : 'pb-0'}`}
                >
                  <button
                    onClick={() => toggleQuestion(idx)}
                    className="w-full flex items-center justify-between py-6 text-left group focus:outline-none"
                  >
                    <span className={`text-sm md:text-base font-bold transition-colors duration-300 ${openQuestion === idx ? 'text-[#10221c]' : 'text-slate-700 group-hover:text-emerald-600'}`}>
                      {item.q}
                    </span>
                    <span className={`material-icons-outlined text-slate-300 transition-transform duration-500 font-light flex-shrink-0 ml-4
                      ${openQuestion === idx ? 'rotate-180 text-emerald-500' : 'rotate-0'}`}
                    >
                      expand_more
                    </span>
                  </button>

                  <div className={`overflow-hidden transition-all duration-500 ease-in-out ${openQuestion === idx ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'}`}>
                    <div className="text-slate-500 text-sm leading-relaxed font-medium md:pr-10">
                      {item.a}
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* Support Call-to-action */}
            <div className="mt-16 p-8 bg-slate-50 rounded-2xl flex flex-col md:flex-row items-center justify-between gap-6 border border-slate-100">
               <div className="text-center md:text-left">
                  <h4 className="text-sm font-bold uppercase tracking-widest mb-1">Still need help?</h4>
                  <p className="text-xs text-slate-400">Our lifestyle curators are available 24/7 to assist you.</p>
               </div>
               <div className="flex gap-4 w-full md:w-auto">
                  <button className="flex-1 md:flex-none px-6 py-3 bg-[#10221c] text-white text-[10px] font-bold uppercase tracking-widest hover:bg-emerald-600 transition-colors shadow-sm">
                    Live Chat
                  </button>
                  <button className="flex-1 md:flex-none px-6 py-3 bg-white border border-slate-200 text-[#10221c] text-[10px] font-bold uppercase tracking-widest hover:border-[#10221c] transition-colors">
                    Contact Us
                  </button>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FAQ;
